<?php
require_once __DIR__ . '/includes/bootstrap.php'; require_once __DIR__ . '/config/db.php';
if (empty($_SESSION['user_id']) || !in_array($_SESSION['user_role'] ?? '', ['student','tutor'], true)) { header('Location: auth/login.php'); exit; }
$role=$_SESSION['user_role']; $user=(int)$_SESSION['user_id']; $availability=[]; $bookings=[]; $notice='';
try { $pdo=db(); if($role==='tutor'){ $q=$pdo->prepare('SELECT id FROM tutors WHERE user_id=?');$q->execute([$user]);$tutorId=(int)$q->fetchColumn(); if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf($_POST['csrf_token']??null)){if(isset($_POST['delete'])){$q=$pdo->prepare('DELETE FROM availability WHERE id=? AND tutor_id=?');$q->execute([(int)$_POST['delete'],$tutorId]);}elseif(isset($_POST['day'])){$q=$pdo->prepare('INSERT INTO availability(tutor_id,day_of_week,start_time,end_time,is_recurring) VALUES(?,?,?,?,1)');$q->execute([$tutorId,$_POST['day'],$_POST['start'],$_POST['end']]);}$notice='Availability updated.';} $q=$pdo->prepare('SELECT * FROM availability WHERE tutor_id=? ORDER BY start_time');$q->execute([$tutorId]);$availability=$q->fetchAll(); $condition='b.tutor_id=:id';$params=['id'=>$tutorId]; }else{$condition='b.student_id=:id';$params=['id'=>$user];} $q=$pdo->prepare("SELECT b.*,s.name subject,u.full_name other_name FROM bookings b JOIN subjects s ON s.id=b.subject_id JOIN tutors t ON t.id=b.tutor_id JOIN users u ON u.id=".($role==='tutor'?'b.student_id':'t.user_id')." WHERE $condition AND b.booking_date>=CURDATE() ORDER BY b.booking_date,b.start_time");$q->execute($params);$bookings=$q->fetchAll(); }catch(Throwable $e){}
$pageTitle='Schedule';require __DIR__.'/includes/header.php';require __DIR__.'/includes/navbar.php';
?><main class="section-soft py-5"><div class="container"><h1 class="h2">My schedule</h1><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><div class="profile-section mt-3"><h2 class="h5">Weekly schedule</h2><div class="availability-grid"><?php foreach(['Sat','Sun','Mon','Tue','Wed','Thu','Fri'] as $day):?><div class="availability-day"><strong><?=$day?></strong><?php foreach($bookings as $b):if(date('D',strtotime($b['booking_date']))===$day):?><div class="slot-link <?=$b['status']==='pending'?'bg-warning-subtle text-dark':''?>"><?=date('g:i A',strtotime($b['start_time']))?><br><small><?=e($b['subject'])?></small></div><?php endif;endforeach;?></div><?php endforeach;?></div></div><?php if($role==='tutor'):?><div class="profile-section mt-4"><h2 class="h5">Available slots</h2><form method="post" class="row g-2 mb-3"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="col"><select class="form-select" name="day"><?php foreach(['Sat','Sun','Mon','Tue','Wed','Thu','Fri'] as $d):?><option><?=$d?></option><?php endforeach;?></select></div><div class="col"><input class="form-control" type="time" name="start" required></div><div class="col"><input class="form-control" type="time" name="end" required></div><div class="col-auto"><button class="btn btn-brand">Add</button></div></form><?php foreach($availability as $a):?><div class="border-top py-2"><?=e($a['day_of_week'])?> <?=e($a['start_time'])?>–<?=e($a['end_time'])?><form method="post" class="d-inline float-end"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button class="btn btn-sm text-danger" name="delete" value="<?=$a['id']?>">Delete</button></form></div><?php endforeach;?></div><?php endif;?><div class="profile-section mt-4"><h2 class="h5">Upcoming classes</h2><?php foreach($bookings as $b):?><div class="border-top py-2"><strong><?=e($b['subject'])?></strong> with <?=e($b['other_name'])?><span class="float-end badge text-bg-<?=$b['status']==='accepted'?'success':'warning'?>"><?=e($b['status'])?></span><br><small class="text-secondary"><?=e($b['booking_date'])?> · <?=date('g:i A',strtotime($b['start_time']))?></small></div><?php endforeach;if(!$bookings):?><p class="text-secondary mb-0">No upcoming classes.</p><?php endif;?></div></div></main><?php require __DIR__.'/includes/footer.php';?>
